/* the file made (32 KB, padded with $FF) unless it is there with this content */
static void vx_testcart_write (const char *path)
{
	static unsigned char im[32768], old[32768]; memset (im, 0xFF, sizeof im); memcpy (im, VX_TESTCART, sizeof VX_TESTCART);
	FILE *f = fopen (path, "rb"); if (f) { size_t n = fread (old, 1, sizeof old, f); fclose (f); if (n == sizeof old && !memcmp (old, im, sizeof im)) return; }
	f = fopen (path, "wb"); if (f) { fwrite (im, 1, sizeof im, f); fclose (f); }
}
